function dismissMessage(){ $('#toast').classList.remove('show'); }
function toast(text){if(!text)return;$('#message-text').textContent=plain(text);const el=$('#comms-feedback');if(el)el.textContent=plain(text);}
function syncComms(){const dock=$('#comms-dock');if(!dock)return;const key=JSON.stringify([(state.world?.feed||[]).at(-1)?.id,state.activeIncident?.id,commsExpanded]);if(key===commsKey)return;commsKey=key;const list=dock.querySelector('.comms-messages');const keep=list&&list.scrollHeight-list.scrollTop-list.clientHeight>40;const top=list?.scrollTop||0;const focused=dock.contains(document.activeElement)?{event:document.activeElement.dataset.openEvent,toggle:document.activeElement.hasAttribute('data-comms-toggle')}:null;dock.innerHTML=renderComms(state,esc,commsExpanded);const next=dock.querySelector('.comms-messages');if(next)next.scrollTop=keep?top:next.scrollHeight;if(focused?.event)dock.querySelector(`[data-open-event="${focused.event}"]`)?.focus();else if(focused?.toggle)dock.querySelector('[data-comms-toggle]')?.focus();}
