function completionMessage(before,after){const lines=[];for(const event of after.events||[]){const old=new Set((before.events?.find(e=>e.id===event.id)?.entries||[]).map(e=>e.id));for(const entry of event.entries||[])if(!old.has(entry.id)&&entry.type==='完成回報')lines.push(`${entry.actor}：${entry.text}`);}return lines.length?lines.join('\n'):after.last;}
