 const spots={dorm:[['置物櫃','inventory',32,42],['上一班的提醒','briefing',65,34]],canteen:[['配給窗口','logistics',36,40],['上一班的提醒','briefing',65,31]],gate:[['門禁終端','terminal',28,49],['對講機','visitor',53,43]],engineering:[['工程師','engineer',61,42],['設備工單','routine',28,34]]}[state.location]||[['本職務工作台','roleWork',45,45],['設備細節','details',70,32]];$('#hotspots').innerHTML=state.ended?'':spots.map(([label,panel,x,y],i)=>`<button class="hotspot" data-ui="${panel}" style="left:${x}%;top:${y}%"><span class="pin">${i+1}</span>${label}</button>`).join('');
